import{_ as e,c as a,o as s,a3 as r}from"./chunks/framework.Dokpd4od.js";const p=JSON.parse('{"title":"Get started with Project","description":"","frontmatter":{},"headers":[],"relativePath":"master/services/project/get-started/index.md","filePath":"master/services/project/get-started/index.md","lastUpdated":1793074831000}'),o={name:"master/services/project/get-started/index.md"};function n(d,t,i,c,l,h){return s(),a("div",null,t[0]||(t[0]=[r('<h1 id="get-started-with-project" tabindex="-1">Get started with Project <a class="header-anchor" href="#get-started-with-project" aria-label="Permalink to &quot;Get started with Project&quot;">​</a></h1><p>Before you create your first project, decide which features you want. Project has three switches in <strong>Settings</strong>. They add fields and pages to your projects and tasks. After that you add a few records that every project needs.</p><blockquote><p><strong>In simple words:</strong> Turn on what you need, add stages and tags, then create a project.</p></blockquote><h2 id="setup-order" tabindex="-1">Setup order <a class="header-anchor" href="#setup-order" aria-label="Permalink to &quot;Setup order&quot;">​</a></h2><ol><li>Open the <a href="./project-settings.html">Project settings</a>. Switch on <strong>Enable Project Stages</strong>, <strong>Enable Milestones</strong> and <strong>Enable Timesheets</strong> as needed.</li><li>Open <code>Project → Configurations → Project Stages</code>. Add the phases of a project. Example: <strong>To Do</strong>, <strong>In Progress</strong>, <strong>Done</strong>, <strong>Cancelled</strong>. See <a href="./../project-management/project-stages-and-milestones.html">Project stages and milestones</a>.</li><li>Open <code>Project → Configurations → Tags</code>. Add labels such as <strong>Design</strong> or <strong>Client Work</strong>. See <a href="./../configuration/tags.html">Tags</a>.</li><li><a href="./../project-management/create-project.html">Create a project</a>.</li><li>Add task stages to that project, such as <strong>New</strong>, <strong>In Progress</strong>, <strong>Review</strong> and <strong>Done</strong>. See <a href="./../task-management/task-stages-and-states.html">Task stages and states</a>.</li><li><a href="./../task-management/create-task.html">Create a task</a>.</li></ol><div class="warning custom-block"><p class="custom-block-title">Task stages come first</p><p>A new project has no task stages. A task cannot be saved until its project has at least one stage. Add the stages before you create tasks.</p></div><h2 id="what-each-switch-adds" tabindex="-1">What each switch adds <a class="header-anchor" href="#what-each-switch-adds" aria-label="Permalink to &quot;What each switch adds&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Switch</th><th>What it adds</th></tr></thead><tbody><tr><td><strong>Enable Project Stages</strong></td><td>A stage bar at the top of the project form</td></tr><tr><td><strong>Enable Milestones</strong></td><td><strong>Allow Milestones</strong> on projects, a <strong>Milestone</strong> field on tasks</td></tr><tr><td><strong>Enable Timesheets</strong></td><td><strong>Allow Timesheets</strong>, hours fields, a <strong>Timesheets</strong> tab on tasks</td></tr></tbody></table><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./project-settings.html">Project settings</a></li><li><a href="./../">Project overview</a></li><li><a href="./../project-management/">Project management</a></li></ul>',10)]))}const m=e(o,[["render",n]]);export{p as __pageData,m as default};
